    out.phase='committing'; out.transcript=tr;
    out.action = pendingAction; out.confidence = pendingConfidence;
    out.close = true;
    out.reply = 'Committed: ' + (out.action || 'your action') + ' (within 24h). I will check in tomorrow.';
    return [{json:out}];
